            onClick={() => {
              if (newMessage.trim()) {
                setMessages([...messages, {
                  sender: currentUser?.phone,
                  text: newMessage,
                  time: new Date().toLocaleTimeString()
                }]);
                setNewMessage('');
              }
            }}
          >
            Send
          </button>
        </div>
      </div>
    );
  };

  // Render Profile Modal
  const renderProfileModal = () => {
    return (
      <div className="modal-overlay" onClick={() => setShowProfile(false)}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => setShowProfile(false)}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{currentUser?.name?.charAt(0) || '?'}</div>
            <h2>{currentUser?.name}</h2>
            <p>{currentUser?.age} years • {currentUser?.town}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item">
              <span className="label">📞 Phone</span>
              <span>{currentUser?.phone}</span>
            </div>
            <div className="profile-item">
              <span className="label">🎓 Education</span>
              <span>{currentUser?.education || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">💼 Profession</span>
              <span>{currentUser?.profession || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">💍 Marital Status</span>
              <span>{currentUser?.maritalStatus || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🙏 Religion</span>
              <span>{currentUser?.religion || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🌍 Ethnicity</span>
              <span>{currentUser?.ethnicity || 'Not specified'}</span>
            </div>
            <div className="profile-item full-width">
              <span className="label">💭 About Me</span>
              <span>{currentUser?.description || 'No description yet'}</span>
            </div>
          </div>
          <button className="btn-primary full-width" onClick={() => setShowProfile(false)}>
            Close Profile
          </button>
        </div>
      </div>
    );
  };

  // Render Match Details Modal
  const renderMatchDetails = () => {
    const match = matches[currentMatchIndex];
    if (!match) return null;

    return (
      <div className="modal-overlay" onClick={() => setShowMatchDetails(false)}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => setShowMatchDetails(false)}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{match.name?.charAt(0) || '?'}</div>
            <h2>{match.name}</h2>
            <p>{match.age} years • {match.town}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item">
              <span className="label">💼 Profession</span>
              <span>{match.profession || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🎓 Education</span>
              <span>{match.education || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">💍 Marital Status</span>
              <span>{match.maritalStatus || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🙏 Religion</span>
              <span>{match.religion || 'Not specified'}</span>
            </div>
            <div className="profile-item">
              <span className="label">🌍 Ethnicity</span>
              <span>{match.ethnicity || 'Not specified'}</span>
            </div>
            {match.description && (
              <div className="profile-item full-width">
                <span className="label">💭 About Me</span>
                <span>{match.description}</span>
              </div>
            )}
          </div>
          <div className="modal-actions">
            <button 
              className="btn-secondary"
              onClick={() => setShowMatchDetails(false)}
            >
              Close
            </button>
            <button 
              className="btn-primary"
              onClick={() => {
                expressInterest(match.phone);
                setShowMatchDetails(false);
              }}
            >
              💕 Express Interest
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="app">
      {isLoggedIn ? renderMainApp() : (showActivation ? renderActivation() : renderRegistration())}
    </div>
  );
}

export default App;
